use nalgebra::SMatrix;
pub fn setup_action_gj(
    m: &SMatrix<f64, 10, 10>,
    c: &SMatrix<f64, 1, 10>,
    _: f64,
    action: &mut SMatrix<f64, 16, 16>,
) -> Option<()> {
    let mut m1 = SMatrix::<f64, 5, 29>::zeros();

    fill_m1_0_0(m, c, &mut m1);
    fill_m1_0_1(m, c, &mut m1);
    fill_m1_0_2(m, c, &mut m1);

    let inv = m1.fixed_view::<4, 4>(0, 0).into_owned().try_inverse()?;

    let p2 = inv * m1.fixed_view::<4, 29>(0, 0);

    m1.fixed_view_mut::<4, 29>(0, 0).copy_from(&p2);

    let mut m2 = vec![vec![0.0; 412]; 395];

    fill_template_group_0(&m1, &mut m2);
    fill_template_group_1(&m1, &mut m2);
    fill_template_group_2(&m1, &mut m2);
    fill_template_group_3(&m1, &mut m2);

    if !crate::math::gauss_jordan::gauss_jordan(&mut m2, 340) {
        return None;
    }

    *action = SMatrix::zeros();

    for s in 0..16 {
        action[(0, s)] -= m2[340][396 + s];
    }
    for s in 0..16 {
        action[(1, s)] -= m2[372][396 + s];
    }
    for s in 0..16 {
        action[(2, s)] -= m2[373][396 + s];
    }
    for s in 0..16 {
        action[(3, s)] -= m2[374][396 + s];
    }
    action[(4, 0)] = 1.0;

    for s in 0..16 {
        action[(5, s)] -= m2[389][396 + s];
    }
    for s in 0..16 {
        action[(6, s)] -= m2[390][396 + s];
    }
    action[(7, 1)] = 1.0;

    action[(8, 2)] = 1.0;

    action[(9, 3)] = 1.0;

    action[(10, 4)] = 1.0;

    action[(11, 7)] = 1.0;

    action[(12, 8)] = 1.0;

    action[(13, 9)] = 1.0;

    action[(14, 10)] = 1.0;

    action[(15, 14)] = 1.0;

    Some(())
}

#[inline]
fn fill_m1_0_0(m: &SMatrix<f64, 10, 10>, c: &SMatrix<f64, 1, 10>, m1: &mut SMatrix<f64, 5, 29>) {
    m1[(0, 0)] = 4.0 * m[(0, 0)];
    m1[(0, 1)] = 4.0 * m[(4, 0)] + 2.0 * m[(0, 4)];
    m1[(0, 2)] = 2.0 * m[(4, 4)] + 4.0 * m[(1, 0)];
    m1[(0, 3)] = 2.0 * m[(1, 4)];
    m1[(0, 4)] = 4.0 * m[(5, 0)] + 2.0 * m[(0, 5)];
    m1[(0, 5)] = 4.0 * m[(7, 0)] + 2.0 * m[(5, 4)] + 2.0 * m[(4, 5)];
    m1[(0, 6)] = 2.0 * m[(7, 4)] + 2.0 * m[(1, 5)];
    m1[(0, 7)] = 2.0 * m[(5, 5)] + 4.0 * m[(2, 0)];
    m1[(0, 8)] = 2.0 * m[(7, 5)] + 2.0 * m[(2, 4)];
    m1[(0, 9)] = 2.0 * m[(2, 5)];
    m1[(0, 10)] = 4.0 * m[(6, 0)] + 2.0 * m[(0, 6)];
    m1[(0, 11)] = 4.0 * m[(8, 0)] + 2.0 * m[(6, 4)] + 2.0 * m[(4, 6)];
    m1[(0, 12)] = 2.0 * m[(8, 4)] + 2.0 * m[(1, 6)];
    m1[(0, 13)] = 4.0 * m[(9, 0)] + 2.0 * m[(6, 5)] + 2.0 * m[(5, 6)];
    m1[(0, 14)] = 2.0 * m[(9, 4)] + 2.0 * m[(8, 5)] + 2.0 * m[(7, 6)];
    m1[(0, 15)] = 2.0 * m[(9, 5)] + 2.0 * m[(2, 6)];
    m1[(0, 16)] = 2.0 * m[(6, 6)] + 4.0 * m[(3, 0)];
    m1[(0, 17)] = 2.0 * m[(8, 6)] + 2.0 * m[(3, 4)];
    m1[(0, 18)] = 2.0 * m[(9, 6)] + 2.0 * m[(3, 5)];
    m1[(0, 19)] = 2.0 * m[(3, 6)];
    m1[(0, 24)] = 4.0 * c[(0, 0)];
    m1[(0, 25)] = 2.0 * c[(0, 4)];
    m1[(0, 26)] = 2.0 * c[(0, 5)];
    m1[(0, 27)] = 2.0 * c[(0, 6)];
    m1[(1, 0)] = 2.0 * m[(0, 4)];
    m1[(1, 1)] = 2.0 * m[(4, 4)] + 4.0 * m[(0, 1)];
    m1[(1, 2)] = 4.0 * m[(4, 1)] + 2.0 * m[(1, 4)];
    m1[(1, 3)] = 4.0 * m[(1, 1)];
    m1[(1, 4)] = 2.0 * m[(5, 4)] + 2.0 * m[(0, 7)];
    m1[(1, 5)] = 2.0 * m[(7, 4)] + 4.0 * m[(5, 1)] + 2.0 * m[(4, 7)];
    m1[(1, 6)] = 4.0 * m[(7, 1)] + 2.0 * m[(1, 7)];
    m1[(1, 7)] = 2.0 * m[(5, 7)] + 2.0 * m[(2, 4)];
    m1[(1, 8)] = 2.0 * m[(7, 7)] + 4.0 * m[(2, 1)];
    m1[(1, 9)] = 2.0 * m[(2, 7)];
    m1[(1, 10)] = 2.0 * m[(6, 4)] + 2.0 * m[(0, 8)];
    m1[(1, 11)] = 2.0 * m[(8, 4)] + 4.0 * m[(6, 1)] + 2.0 * m[(4, 8)];
    m1[(1, 12)] = 4.0 * m[(8, 1)] + 2.0 * m[(1, 8)];
    m1[(1, 13)] = 2.0 * m[(9, 4)] + 2.0 * m[(6, 7)] + 2.0 * m[(5, 8)];
    m1[(1, 14)] = 4.0 * m[(9, 1)] + 2.0 * m[(8, 7)] + 2.0 * m[(7, 8)];
    m1[(1, 15)] = 2.0 * m[(9, 7)] + 2.0 * m[(2, 8)];
    m1[(1, 16)] = 2.0 * m[(6, 8)] + 2.0 * m[(3, 4)];
    m1[(1, 17)] = 2.0 * m[(8, 8)] + 4.0 * m[(3, 1)];
    m1[(1, 18)] = 2.0 * m[(9, 8)] + 2.0 * m[(3, 7)];
    m1[(1, 19)] = 2.0 * m[(3, 8)];
    m1[(1, 24)] = 2.0 * c[(0, 4)];
    m1[(1, 25)] = 4.0 * c[(0, 1)];
    m1[(1, 26)] = 2.0 * c[(0, 7)];
    m1[(1, 27)] = 2.0 * c[(0, 8)];
}
